import{_ as a,c as t,o as r,aj as n}from"./chunks/framework.BlveriQe.js";const m=JSON.parse('{"title":"Interface: InvitationsAPI","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/InvitationsAPI.md","filePath":"reference/js-bao-wss-client/api/interfaces/InvitationsAPI.md"}'),o={name:"reference/js-bao-wss-client/api/interfaces/InvitationsAPI.md"};function i(s,e,d,c,l,h){return r(),t("div",null,[...e[0]||(e[0]=[n('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / InvitationsAPI</p><h1 id="interface-invitationsapi" tabindex="-1">Interface: InvitationsAPI <a class="header-anchor" href="#interface-invitationsapi" aria-label="Permalink to “Interface: InvitationsAPI”">​</a></h1><p>Sub-API for app-level invitations and deferred grants.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="accept" tabindex="-1">accept() <a class="header-anchor" href="#accept" aria-label="Permalink to “accept()”">​</a></h3><blockquote><p><strong>accept</strong>(<code>inviteToken</code>): <code>Promise</code>&lt;<a href="./AcceptInviteResult.html"><code>AcceptInviteResult</code></a>&gt;</p></blockquote><p>Accept an invitation via its invite token.</p><p>For authenticated users whose session already exists (e.g. they signed up with a different email than the invited one, or were invited after signup). The server marks the invitation accepted (write-once) and binds all pending deferred grants linked to it to the caller&#39;s userId.</p><p>Throws on any invite-token failure (invalid / expired / already-accepted) with <code>AUTH_CODES.INVITE_TOKEN_INVALID</code>. The server returns a uniform 401 + <code>INVITE_TOKEN_INVALID</code> for all failure modes rather than distinct codes, so the response does not reveal whether an underlying invitation exists.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="invitetoken" tabindex="-1">inviteToken <a class="header-anchor" href="#invitetoken" aria-label="Permalink to “inviteToken”">​</a></h5><p><code>string</code></p><p>The invitation token from the accept URL</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./AcceptInviteResult.html"><code>AcceptInviteResult</code></a>&gt;</p><hr><h3 id="create" tabindex="-1">create() <a class="header-anchor" href="#create" aria-label="Permalink to “create()”">​</a></h3><blockquote><p><strong>create</strong>(<code>params</code>): <code>Promise</code>&lt;<a href="./AppInvitationInfo.html"><code>AppInvitationInfo</code></a>&gt;</p></blockquote><p>Create an app-level invitation. Members can create invitations when <code>memberInvitationsEnabled</code> is true. Admins/owners can always create invitations.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="params" tabindex="-1">params <a class="header-anchor" href="#params" aria-label="Permalink to “params”">​</a></h5><p><a href="./CreateInvitationParams.html"><code>CreateInvitationParams</code></a></p><p>Invitation details</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./AppInvitationInfo.html"><code>AppInvitationInfo</code></a>&gt;</p><hr><h3 id="delete" tabindex="-1">delete() <a class="header-anchor" href="#delete" aria-label="Permalink to “delete()”">​</a></h3><blockquote><p><strong>delete</strong>(<code>invitationId</code>): <code>Promise</code>&lt;{ <code>message</code>: <code>string</code>; <code>success</code>: <code>boolean</code>; }&gt;</p></blockquote><p>Delete (revoke) an app-level invitation.</p><p>Admins and owners can revoke any invitation. A member can revoke only invitations they created themselves (403 otherwise). Revoking an active invitation frees the member&#39;s quota. Also cascade-deletes any linked deferred grants.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="invitationid" tabindex="-1">invitationId <a class="header-anchor" href="#invitationid" aria-label="Permalink to “invitationId”">​</a></h5><p><code>string</code></p><p>The invitation to delete</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;{ <code>message</code>: <code>string</code>; <code>success</code>: <code>boolean</code>; }&gt;</p><hr><h3 id="get" tabindex="-1">get() <a class="header-anchor" href="#get" aria-label="Permalink to “get()”">​</a></h3><blockquote><p><strong>get</strong>(<code>invitationId</code>): <code>Promise</code>&lt;<a href="./AppInvitationInfo.html"><code>AppInvitationInfo</code></a>&gt;</p></blockquote><p>Fetch a single app invitation by id.</p><p>Returns the full invitation envelope, including <code>inviteToken</code> so callers can build their own accept-page CTA (e.g. <code>${baseUrl}/invite/accept?inviteToken=…</code>). The platform does not compose accept URLs because apps own their own accept-page routing.</p><p>Permissions: app admin/owner, OR the invitation&#39;s original inviter. Members who did not create the invitation receive 403 — <code>inviteToken</code> is a bearer credential, so read access is intentionally narrow.</p><p>Legacy invitations with no token are lazily upgraded on first read.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="invitationid-1" tabindex="-1">invitationId <a class="header-anchor" href="#invitationid-1" aria-label="Permalink to “invitationId”">​</a></h5><p><code>string</code></p><p>The invitation to look up</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./AppInvitationInfo.html"><code>AppInvitationInfo</code></a>&gt;</p><hr><h3 id="list" tabindex="-1">list() <a class="header-anchor" href="#list" aria-label="Permalink to “list()”">​</a></h3><blockquote><p><strong>list</strong>(<code>options?</code>): <code>Promise</code>&lt;<a href="./InvitationListResult.html"><code>InvitationListResult</code></a>&gt;</p></blockquote><p>List app-level invitations.</p><p>Admins and owners see the full app list. Members see only the invitations they created themselves — the <code>memberInvitationsEnabled</code> flag gates <em>creating</em> invitations, not listing your own (a member can always see and revoke invitations they already sent). A member with no invitations of their own gets an empty list, not a 403.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="options" tabindex="-1">options? <a class="header-anchor" href="#options" aria-label="Permalink to “options?”">​</a></h5><p><a href="./InvitationListOptions.html"><code>InvitationListOptions</code></a></p><p>Pagination options</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./InvitationListResult.html"><code>InvitationListResult</code></a>&gt;</p><hr><h3 id="listdeferredgrants" tabindex="-1">listDeferredGrants() <a class="header-anchor" href="#listdeferredgrants" aria-label="Permalink to “listDeferredGrants()”">​</a></h3><blockquote><p><strong>listDeferredGrants</strong>(<code>options?</code>): <code>Promise</code>&lt;<a href="./DeferredGrantListResult.html"><code>DeferredGrantListResult</code></a>&gt;</p></blockquote><p>List pending deferred grants (admin/owner only). Deferred grants are permissions/memberships created for users who haven&#39;t signed up yet.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="options-1" tabindex="-1">options? <a class="header-anchor" href="#options-1" aria-label="Permalink to “options?”">​</a></h5><p><a href="./DeferredGrantListOptions.html"><code>DeferredGrantListOptions</code></a></p><p>Filter and pagination options</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./DeferredGrantListResult.html"><code>DeferredGrantListResult</code></a>&gt;</p><hr><h3 id="quota" tabindex="-1">quota() <a class="header-anchor" href="#quota" aria-label="Permalink to “quota()”">​</a></h3><blockquote><p><strong>quota</strong>(): <code>Promise</code>&lt;<a href="./InvitationQuota.html"><code>InvitationQuota</code></a>&gt;</p></blockquote><p>Check the current user&#39;s invitation quota. Admins/owners always get <code>unlimited: true</code>.</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./InvitationQuota.html"><code>InvitationQuota</code></a>&gt;</p><hr><h3 id="revokedeferredgrant" tabindex="-1">revokeDeferredGrant() <a class="header-anchor" href="#revokedeferredgrant" aria-label="Permalink to “revokeDeferredGrant()”">​</a></h3><blockquote><p><strong>revokeDeferredGrant</strong>(<code>deferredId</code>, <code>type</code>): <code>Promise</code>&lt;<a href="./DeferredGrantRevokeResult.html"><code>DeferredGrantRevokeResult</code></a>&gt;</p></blockquote><p>Revoke a deferred grant. Admins/owners can revoke any; the original granter can revoke their own.</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="deferredid" tabindex="-1">deferredId <a class="header-anchor" href="#deferredid" aria-label="Permalink to “deferredId”">​</a></h5><p><code>string</code></p><p>The deferred grant to revoke</p><h5 id="type" tabindex="-1">type <a class="header-anchor" href="#type" aria-label="Permalink to “type”">​</a></h5><p><code>&quot;group&quot;</code> | <code>&quot;document&quot;</code></p><p>Whether this is a &quot;document&quot; or &quot;group&quot; deferred grant</p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./DeferredGrantRevokeResult.html"><code>DeferredGrantRevokeResult</code></a>&gt;</p>',91)])])}const f=a(o,[["render",i]]);export{m as __pageData,f as default};
